  /**
   * Url
   *
   * where it is when it isn't the archive's: a web page (web), a page of Lens's docs (docs), this server (server), or a message or event at its account (mail, event); the citation opens it
   */
  url?: string | null;
  /**
   * Site
   *
   * a web page's site, like example.com; a message's or event's connection
   */
  site?: string | null;
  /**
   * Fetched At
   *
   * when the web page or search result was read
   */
  fetched_at?: string | null;
  /**
   * Title
   */
  title?: string | null;
  /**
   * Namespace
   */
  namespace?: string | null;
  /**
   * Recorded At
   */
  recorded_at?: string | null;
  /**
   * T0
   */
  t0?: number | number | null;
  /**
   * Time
   *
   * where it is: a time ("12:34"), or for a document its page ("p. 3")
   */
  time?: string | null;
  /**
   * Page
   *
   * a document's or an image's page it's on (from 0)
   */
  page?: number | null;
  /**
   * Speaker
   */
  speaker?: string | null;
  /**
   * Text
   */
