export type ListRecordingsData = {
  body?: never;
  path?: never;
  query?: {
    /**
     * Ns
     *
     * one namespace (default: every namespace you can read)
     */
    ns?: string | null;
    /**
     * Q
     *
     * words that must all appear in the title, the namespace or a person's name
     */
    q?: string | null;
    /**
     * Status
     *
     * asset statuses, or processing (a job is queued or running) and failed (the latest job failed); repeat for several (any of them matches)
     */
    status?: Array<"new" | "transcribed" | "diarized" | "analyzed" | "error" | "processing" | "failed"> | null;
    /**
     * Attention
     *
     * only assets that need attention: errored, latest job failed, or a person match to review
     */
    attention?: boolean;
    /**
     * Processing
     *
     * only assets with a job queued or running
     */
    processing?: boolean;
    /**
     * Speaker
     *
     * person ids; repeat for several (any of them matches)
     */
    speaker?: Array<number> | null;
    /**
     * From
     *
     * recorded on or after this day
     */
    from?: string | null;
    /**
     * To
     *
     * recorded on or before this day
     */
    to?: string | null;
    /**
     * Min Duration
     *
     * at least this many seconds long
     */
    min_duration?: number | null;
    /**
     * Max Duration
     *
     * shorter than this many seconds
     */
    max_duration?: number | null;
    /**
     * Media
     *
     * audio, video, `transcript` (text without media), document or image
     */
    media?: "audio" | "video" | "transcript" | "document" | "image" | null;
    /**
     * Access
     *
     * public, restricted or private; repeat for several
     */
    access?: Array<"public" | "restricted" | "private"> | null;
    /**
     * Featured
     *
     * only featured assets (true) or only the others (false)
     */
    featured?: boolean | null;
    /**
     * Tag
     *
     * tags (ignoring case); repeat for several (any of them matches)
     */
    tag?: Array<string> | null;
    /**
     * Origin
     *
     * where they came from: source:<id> (a connected source), upload, paste, iiif, folder (the archive's own folders) or file; repeat for several
     */
    origin?: Array<string> | null;
    /**
     * Language
     *
     * language codes (ignoring case), none for assets whose language isn't known; repeat for several
     */
    language?: Array<string> | null;
    /**
     * Object
     *
     * kinds of object seen in it (person, car, dog …; ignoring case); repeat for several (any of them matches)
     */
    object?: Array<string> | null;
    /**
     * Edited By
     *
     * me: assets you edited (corrected the text, changed the catalogue record or renamed)
     */
    edited_by?: "me" | null;
    /**
     * Sensitive
     *
     * where NSFW classification is on (docs/nsfw.md): only those flagged NSFW, exclude them, or include them. Without it, flagged ones are left out where their namespace hides them (display hide)
     */
    sensitive?: "include" | "only" | "exclude" | null;
    /**
     * Face
     *
     * face identity ids: the assets they're seen in; repeat for several
     */
    face?: Array<number> | null;
    /**
     * Entity
     *
     * entity ids: the assets mentioning them; repeat for several
     */
    entity?: Array<number> | null;
    /**
     * Topic
     *
     * topic ids: the assets accepted as about them (not their narrower topics); repeat for several
     */
    topic?: Array<number> | null;
    /**
     * Content Type
     *
     * content type keys (podcast, scan, email …; GET /content-types): their assets; repeat for several
     */
    content_type?: Array<string> | null;
    /**
     * Emotion
     *
     * emotions heard in them (ignoring case); repeat for several
     */
    emotion?: Array<string> | null;
    /**
     * Collection
     *
     * a collection: the assets in it and in the collections inside it
     */
    collection?: number | null;
    /**
     * Field
     *
     * a custom field (of resources): the assets with a value for it, or with `value`
     */
    field?: number | null;
    /**
     * Value
     *
     * with `field`: text that its value contains, the number, a date it starts with (1998, 1998-05), true/false, or one of its options
     */
    value?: string | null;
    /**
     * Sort
     *
     * date, title, duration, speakers (number of people), status or importance; prefix - for descending
     */
    sort?:
      | "date"
      | "-date"
      | "title"
      | "-title"
      | "duration"
      | "-duration"
      | "speakers"
      | "-speakers"
      | "status"
      | "-status"
      | "importance"
      | "-importance";
    /**
     * Limit
     */
    limit?: number;
    /**
     * Offset
     */
    offset?: number;
  };
  url: "/api/v1/resources";
};

